const PRODUCTS = ['BrainIQtest','Chat AI','LoveStyle','Mindspree','Mobitrace','My Image','My QR Code','MyWapp','PDFhelp','Personality','QRcreate','RealChecker','ResumeWise','UniCopy','VinReady'];
const EXT = ['png','jpg','jpeg','webp','gif','mp4','webm','zip','html','htm','eml','pdf','txt','json','csv'];
const bad = /[\\/:*?"<>|#%]/;
function seg(v, label) {
  const s = String(v || '').trim();
  if (!s) throw new Error(label + ' is empty');
  if (s === '.' || s === '..' || s.startsWith('.')) throw new Error(label + ' cannot start with a dot');
  if (bad.test(s)) throw new Error(label + ' contains a character that is not allowed: \\ / : * ? " < > | # %');
  if (s.length > 120) throw new Error(label + ' is longer than 120 characters');
  return s;
}
const product = String($json.product || '').trim();
if (!PRODUCTS.includes(product)) throw new Error('Unknown product "' + product + '". Use one of: ' + PRODUCTS.join(', '));
const run = seg($json.run_folder, 'run_folder');
const subRaw = String($json.subfolder || '').trim();
const subs = subRaw ? subRaw.split('/').map((p, i) => seg(p, 'subfolder part ' + (i + 1))) : [];
if (subs.length > 3) throw new Error('subfolder can have at most 3 levels');
const file = seg($json.file_name, 'file_name');
const ext = (file.split('.').pop() || '').toLowerCase();
if (!file.includes('.') || !EXT.includes(ext)) throw new Error('File type .' + ext + ' not allowed. Allowed: ' + EXT.join(', '));
const parts = ['SHARED COMPANY FOLDER I18N', 'AI AUDITS', product, run, ...subs, file];
const graphPath = parts.map(encodeURIComponent).join('/');
return { json: { graph_url: 'https://graph.microsoft.com/v1.0/me/drive/root:/' + graphPath + ':/createUploadSession', folder: parts.slice(0, -1).join('/'), file_name: file } };

